import { Minus, Plus } from '@hexa-ui/icons';
import React, { useState } from 'react';
import { IconButton } from '../icon-button';
import { Container, Input } from './Quantifier.styles';

export interface QuantifierProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> {
  size?: 'small' | 'medium';
  onClickMinusButton?(e: React.MouseEvent<HTMLButtonElement>): void;
  onClickPlusButton?(e: React.MouseEvent<HTMLButtonElement>): void;
  onValueChange?(value: number): void;
}

const Quantifier = React.forwardRef(
  (
    {
      size = 'small',
      disabled = false,
      min = 0,
      max,
      value: valueFromProps,
      defaultValue,
      onChange: onChangeFromProps,
      onClickMinusButton,
      onClickPlusButton,
      onValueChange,
      ...props
    }: QuantifierProps,
    forwardedRef: React.ForwardedRef<HTMLInputElement>
  ): JSX.Element => {
    const isControlled = valueFromProps !== undefined;
    const [value, setValue] = useState<number>(Number(defaultValue) || 0);
    const mappedValue = isControlled ? Number(valueFromProps) : value;

    const handleClickMinusButton = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (onClickMinusButton && typeof onClickMinusButton === 'function') onClickMinusButton(e);
      if (onValueChange && typeof onValueChange === 'function') {
        onValueChange(Number(value) - 1);
      }
      setValue(Number(value) - 1);
    };

    const handleClickPlusButton = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (onClickPlusButton && typeof onClickPlusButton === 'function') onClickPlusButton(e);
      if (onValueChange && typeof onValueChange === 'function') {
        onValueChange(Number(value) + 1);
      }
      setValue(Number(value) + 1);
    };

    const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (onValueChange && typeof onValueChange === 'function') {
        onValueChange(Math.round(Number(e.target.value)));
      }
      if (onChangeFromProps && typeof onChangeFromProps === 'function') {
        onChangeFromProps(e);
        if (!isControlled) setValue(Math.round(Number(e.target.value)));
        return;
      }
      setValue(Math.round(Number(e.target.value)));
    };

    return (
      <Container size={size}>
        <IconButton
          variant="tertiary"
          size={size === 'small' ? 'tiny' : 'small'}
          icon={Minus}
          disabled={disabled || mappedValue <= min}
          onClick={handleClickMinusButton}
        />
        <Input
          type="number"
          size={size}
          disabled={disabled}
          min={min}
          max={max}
          value={mappedValue}
          onChange={onChange}
          ref={forwardedRef}
          {...props}
        />
        <IconButton
          variant="tertiary"
          size={size === 'small' ? 'tiny' : 'small'}
          icon={Plus}
          disabled={disabled || (max ? mappedValue >= max : false)}
          onClick={handleClickPlusButton}
        />
      </Container>
    );
  }
);

export default Quantifier;
